#!/usr/bin/env tsx

// #region 🔖Header
// Export Nakagin Capsule Tower Design Model to Semio Assets
// 
// This script extracts the Nakagin Capsule Tower design from the Metabolism kit
// and exports it as a model asset to the semio assets folder.
// #endregion 🔖Header

import { readFileSync, writeFileSync } from 'fs';
import { join } from 'path';

// Import semio functions for model serialization
import { serializeModel, Model } from '../../../semio/js/semio.js';
import { MetabolismKitDesigns } from '../../../semio/assets/index.js';

// #region 🔖Main
// Main export logic for Nakagin Capsule Tower design model

interface DesignModel {
  guid: string;
  name: string;
  description?: string;
  pieces?: any[];
  props?: any[];
  // Add other relevant fields from the design structure
}

/**
 * Extract Nakagin Capsule Tower design from Metabolism kit
 */
function extractNakaginCapsuleTowerDesign(): DesignModel | null {
  const nakaginDesigns = MetabolismKitDesigns.filter(design => design.name === "Nakagin Capsule Tower");

  if (nakaginDesigns.length === 0) {
    console.error('❌ Nakagin Capsule Tower design not found in Metabolism kit');
    return null;
  }

  console.log(`✅ Found ${nakaginDesigns.length} Nakagin Capsule Tower design(s)`);
  return nakaginDesigns[0]; // Return the main design
}

/**
 * Convert design to model format
 */
function designToModel(design: DesignModel): Model {
  return {
    guid: design.guid,
    name: design.name,
    // Add other model fields as needed based on the Model schema
    attributes: [],
    tags: []
  };
}

/**
 * Export model to assets folder
 */
function exportModelToAssets(model: Model, outputPath: string): void {
  try {
    const serializedModel = serializeModel(model);
    writeFileSync(outputPath, serializedModel, 'utf8');
    console.log(`✅ Model exported to: ${outputPath}`);
  } catch (error) {
    console.error(`❌ Failed to export model: ${error}`);
    throw error;
  }
}

/**
 * Main execution function
 */
function main(): void {
  console.log('🚀 Starting Nakagin Capsule Tower design model export...');

  // Extract the design
  const design = extractNakaginCapsuleTowerDesign();
  if (!design) {
    process.exit(1);
  }

  // Convert to model format
  const model = designToModel(design);

  // Define output path
  const outputPath = join(__dirname, '../../../semio/assets/models/nakagin-capsule-tower.json');

  // Export the model
  exportModelToAssets(model, outputPath);

  console.log('🎉 Export completed successfully!');
}

// Execute main function
if (require.main === module) {
  main();
}

// #endregion 🔖Main

