  return {
    guid: design.guid,
    name: design.name,
    description: design.description,
    pieces: design.pieces || [],
    props: design.props || [],
    image: design.image,
    icon: design.icon,
    unit: design.unit,
    authors: design.authors || [],
    exportedAt: new Date().toISOString(),
    exportVersion: "1.0.0"
  };
}

