        guid: "description",
        name: "Description", 
        description: "Design description",
        value: design.description || "",
        type: { guid: "string" }
      }
    ],
    tags: [
      { guid: "nakagin-capsule-tower" },
      { guid: "metabolism" },
      { guid: "kurokawa" },
      { guid: "exported-model" }
    ]
